<?php foreach ($q['options'] as $option): ?>
<?php if (in_array($q['type'], ['single', 'multiple'], true)): ?><label class="program-option"><input type="<?=$q['type'] === 'single' ? 'radio' : 'checkbox'?>" name="answers[<?=e($item['id'])?>]<?=$q['type'] === 'multiple' ? '[]' : ''?>" value="<?=e($option['key'])?>" <?=($q['type'] === 'single' ? $item['answer'] === $option['key'] : is_array($item['answer']) && in_array($option['key'], $item['answer'], true)) ? 'checked' : ''?>> <?=e($option['text'])?></label>
<?php else: ?><label><?=e($option['text'])?><input class="form-control" maxlength="500" name="answers[<?=e($item['id'])?>][<?=e($option['key'])?>]" value="<?=e(is_array($item['answer']) ? ($item['answer'][$option['key']] ?? '') : '')?>"></label><?php endif ?>
<?php endforeach ?></fieldset><?php endforeach ?>
<section class="panel"><p>Poți reciti răspunsurile înainte de predare. După predare, tentativa se închide.</p><button class="btn btn-primary" type="submit">Predă examenul <?=icon('arrow')?></button></section></form>
