<?php elseif ($screen === 'lab'): $catalog = json_decode(file_get_contents(ROOT . '/contracts/program/labs.json'), true, 24, JSON_THROW_ON_ERROR); $scenario = $catalog['scenarios'][$model['scenario']]; ?>
<div class="program-columns"><section class="panel"><h2><?=e($model['scenario'] . ' · ' . $scenario['title'])?></h2><p><?=e($scenario['instructions'])?></p><p class="small muted">Laborator virtual. Nu creează produse, loturi sau comenzi pe echipamente reale.</p><h3>Cum se evaluează</h3><ul><?php foreach ($catalog['rubric'] as $criterion): ?><li><?=e($criterion)?>: 0–25 de puncte.</li><?php endforeach ?></ul><p>Minimum 85 de puncte și toate verificările obligatorii. Evaluarea este făcută de o altă persoană.</p><p><strong>Stare:</strong> <?=e(ProgramHtml::state($model['state']))?></p><?php if ($model['checks']): ?><h3>Verificări automate</h3><ul><?php foreach ($model['checks'] as $c): ?><li><?=$c['passed'] ? '✓' : '×'?> <?=e($c['name'])?></li><?php endforeach ?></ul><?php endif; if ($model['review']): ?><h3>Feedbackul evaluatorului</h3><p><?=e($model['review']['reason'])?></p><p><?=array_sum($model['review']['points'])?> / 100 de puncte</p><?php endif ?><a href="/invatare/inscrieri/<?=e($model['enrollment_id'])?>">← Înapoi la curs</a></section>
<section class="panel"><h2>Datele și explicația ta</h2><?php if (!in_array($model['state'], ['validated', 'submitted'], true)): $form('lab_save', $model['id'], ['expected_revision' => $model['revision']]); $area('payload', 'Document JSON al probei', is_array($model['payload']) && $model['payload'] ? $model['payload'] : $scenario['template'], 20); echo '<input type="hidden" name="evidence_asset_id" value="' . e($model['evidence_asset_id'] ?? '') . '">'; $submit('Salvează proba'); $form('lab_submit', $model['id']); $submit('Verifică și trimite evaluatorului', true); else: ?><pre class="program-code"><?=e(json_encode($model['payload'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES))?></pre><?php endif ?>
<details class="mt-4"><summary>Atașează o dovadă privată</summary><p>PNG/JPEG/WebP, cel mult 2 MB. Pentru P04 este necesară dovada probei fizice. Nu include parole sau date personale inutile.</p><div data-program-upload="lab_evidence"><label>Imagine<input class="form-control" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="check-label"><input type="checkbox" data-upload-rights> Confirm dreptul de utilizare.</label><button type="button" class="btn btn-outline-primary" data-upload-button>Încarcă dovada</button><p role="status" data-upload-status></p></div></details></section></div>
<?php endif ?>
